const RARE = ['c', 'b', 't', 'tau', 'vtau'];
let CLG = null, CLBUD = null, CL_RAF = 0;
const CLBAR = qBar('clbar', '💥', 'Mini collider', 'collide-level', () => CLG, () => { if(CLG) CLG.done = true; }, () => drawCol());
